begin;
create temp table _had_note on commit drop as select id from public.areas where parking_note is not null;
update public.areas set parking_note='Drive 0.6 mi from the dam on the south shore. Limited parking: a dirt pullout (about 3 cars) just east of the crag on the south side, one across the road, or a lakeside pullout west toward the dam (5-6 cars).' where id='ca_fisherman_s_buttress_area' and id not in (select id from _had_note);
update public.areas set parking_note='Drive 0.6 mi from the dam on the south shore. Limited parking: a dirt pullout (about 3 cars) just east of the crag on the south side, one across the road, or a lakeside pullout west toward the dam (5-6 cars).' where path <@ (select path from public.areas where id='ca_fisherman_s_buttress_area') and id <> 'ca_fisherman_s_buttress_area' and id not in (select id from _had_note) and parking_note is null and parking_lat is null;
update public.areas set parking_note='Park on Highway 18 about 1 mile from the dam; the lot is about 200 ft past the small signed trailhead, on the left. The trail to Castle Rock is about 1.2 mi and mostly uphill.' where id='ca_castle_rock_area_2' and id not in (select id from _had_note);
update public.areas set parking_note='Park on Highway 18 about 1 mile from the dam; the lot is about 200 ft past the small signed trailhead, on the left. The trail to Castle Rock is about 1.2 mi and mostly uphill.' where path <@ (select path from public.areas where id='ca_castle_rock_area_2') and id <> 'ca_castle_rock_area_2' and id not in (select id from _had_note) and parking_note is null and parking_lat is null;
commit;
